import { TIERS, DEFAULT_TIER } from "./tiers.mjs";
import { isoWeekBounds } from "./iso-week.mjs";

/**
 * README badges — one static SVG (plus a shields.io "endpoint" JSON twin)
 * per project, regenerated by every daily deploy, so a maintainer can drop
 * `![awesomemap](…/badges/<owner>/<repo>.svg)` into their README the same
 * way they'd add a CI badge. Every badge is a lasting backlink, which is
 * the whole point: an awesome-list or leaderboard is visited once, a badge
 * sends traffic for as long as the README carries it.
 *
 * The badge shows the project's *best* standing, not just this week's, so
 * it never decays into "unranked" the week after a spike — a maintainer
 * won't keep a badge that goes blank most of the time. Candidates are this
 * week's live 7-day ranks plus every rank frozen in the weekly archive
 * (awesomemap-data's leaderboard_snapshots, the same source /rising/archive/
 * reads). A project that has never ranked still gets a "Listed in <domain>"
 * badge, so the snippet on its project page is never a dead end.
 */

const TIER_SINGULAR = Object.fromEntries(TIERS.map((tier) => [tier.key, tier.singular]));
const TIER_KEYS = new Set(TIERS.map((tier) => tier.key));

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

// Brand colors, the same three rectangles as the site's favicon/map badge.
const COLOR_LIVE = "#1a8a4a";
const COLOR_PEAK = "#2b5fad";
const COLOR_LISTED = "#6b7280";
const COLOR_LABEL = "#555";

/**
 * Orders two rank candidates: lower rank wins; at equal rank a global rank
 * beats a domain one (it's the harder list to top); then a live rank beats
 * an archived one, and an earlier archived week beats a later one (the
 * date it was *first* reached is what a badge should cite).
 */
function isBetter(candidate, incumbent) {
  if (!incumbent) return true;
  if (candidate.rank !== incumbent.rank) return candidate.rank < incumbent.rank;
  const candidateGlobal = candidate.scope === "global";
  const incumbentGlobal = incumbent.scope === "global";
  if (candidateGlobal !== incumbentGlobal) return candidateGlobal;
  if (!candidate.isoWeek !== !incumbent.isoWeek) return !candidate.isoWeek;
  return (candidate.isoWeek ?? "") < (incumbent.isoWeek ?? "");
}

/**
 * Every project's best archived rank across `weeklySnapshots`
 * (`loadLeaderboardSnapshot` outputs), as a Map of id → `{ rank, tier,
 * scope, isoWeek }`. Reads the tiered `<tier>:<scope>` keys; a pre-tier
 * snapshot (only plain `<scope>` keys) is read as Breakout, which is what
 * those plain keys hold in tiered snapshots too. Spiking is skipped — it
 * isn't a size tier, and "#1 Spiking" on a badge would need its own
 * explanation. `knownScopes`, when given, drops ranks in a scope that no
 * longer exists (a since-removed domain), whose name the badge couldn't
 * print.
 */
export function bestArchivedRanks(weeklySnapshots, { knownScopes = null } = {}) {
  const best = new Map();
  for (const snapshot of weeklySnapshots) {
    const scopes = snapshot?.scopes ?? {};
    const keys = Object.keys(scopes);
    const tiered = keys.some((key) => TIER_KEYS.has(key.split(":")[0]) && key.includes(":"));
    for (const key of keys) {
      let tier;
      let scope;
      if (key.includes(":")) {
        [tier, scope] = key.split(":");
        if (!TIER_KEYS.has(tier)) continue;
      } else {
        if (tiered) continue; // a copy of `breakout:<scope>`, already counted
        tier = DEFAULT_TIER;
        scope = key;
      }
      if (knownScopes && !knownScopes.has(scope)) continue;
      for (const row of scopes[key] ?? []) {
        if (!row?.id || typeof row.rank !== "number") continue;
        const candidate = { rank: row.rank, tier, scope, isoWeek: snapshot.isoWeek };
        if (isBetter(candidate, best.get(row.id))) best.set(row.id, candidate);
      }
    }
  }
  return best;
}

/** "Oct 2026" for an ISO week label, taken from the week's closing Sunday. */
export function isoWeekMonth(isoWeek) {
  const { end } = isoWeekBounds(isoWeek);
  return `${MONTHS[end.getUTCMonth()]} ${end.getUTCFullYear()}`;
}

/**
 * Decides one project's badge text. `liveRanks` is this week's 7-day ranks
 * (`{ rank, tier, scope }`, any number, global and/or domain); `peak` is
 * its `bestArchivedRanks` entry, if any. A domain-scoped rank is named via
 * `domainShortBySlug` — an archived peak can come from another domain the
 * project is also curated into — falling back to `domainShort`, the
 * project's own domain, which the "Listed in" badge also names.
 */
export function pickBadge({ liveRanks = [], peak = null, domainShort, domainShortBySlug = {} }) {
  let best = null;
  for (const candidate of [...liveRanks, peak]) {
    if (candidate && isBetter(candidate, best)) best = candidate;
  }
  if (!best) {
    return { label: "awesomemap", message: `Listed in ${domainShort}`, color: COLOR_LISTED };
  }
  const where = best.scope === "global" ? "overall" : `in ${domainShortBySlug[best.scope] ?? domainShort}`;
  const when = best.isoWeek ? isoWeekMonth(best.isoWeek) : "this week";
  return {
    label: "awesomemap",
    message: `#${best.rank} ${TIER_SINGULAR[best.tier]} ${where} · ${when}`,
    color: best.isoWeek ? COLOR_PEAK : COLOR_LIVE,
  };
}

// Approximate advance widths of Verdana at 11px — the font shields.io
// badges use — so the SVG's boxes fit their text. Only an estimate: the
// text itself is pinned to the computed width with `textLength`, so a
// viewer with a different fallback font gets squeezed glyphs, never
// overflow.
const NARROW = new Set("ijl.,:;'|!·()[]".split(""));
const SEMI = new Set("frtI1 -/".split(""));
const WIDE = new Set("mwMW#%@".split(""));

/** Estimated rendered width of `text` in px at Verdana 11px. */
export function textWidth(text) {
  let width = 0;
  for (const char of text) {
    if (NARROW.has(char)) width += 3.8;
    else if (SEMI.has(char)) width += 4.8;
    else if (WIDE.has(char)) width += 10.2;
    else if (/[A-Z0-9]/.test(char)) width += 7.4;
    else width += 6.6;
  }
  return Math.round(width);
}

function escapeXml(text) {
  return String(text)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

const LOGO_WIDTH = 14;
const PAD = 6;

/**
 * Renders a flat, shields.io-style badge: the treemap logo and `label` on
 * the left, `message` on a `color` background on the right.
 */
export function renderBadgeSvg({ label, message, color }) {
  const labelTextWidth = textWidth(label);
  const messageTextWidth = textWidth(message);
  const labelWidth = PAD + LOGO_WIDTH + 4 + labelTextWidth + PAD;
  const messageWidth = PAD + messageTextWidth + PAD;
  const width = labelWidth + messageWidth;
  const labelTextX = PAD + LOGO_WIDTH + 4;
  const messageTextX = labelWidth + PAD;
  const title = escapeXml(`${label}: ${message}`);
  // Text is drawn twice — a dark copy 1px lower as a shadow, then the
  // white copy — the same legibility trick shields.io badges use.
  const text = (x, value, textLen) => `
    <text x="${x}" y="15" fill="#010101" fill-opacity=".3" textLength="${textLen}" lengthAdjust="spacingAndGlyphs">${escapeXml(value)}</text>
    <text x="${x}" y="14" fill="#fff" textLength="${textLen}" lengthAdjust="spacingAndGlyphs">${escapeXml(value)}</text>`;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="20" role="img" aria-label="${title}">
  <title>${title}</title>
  <linearGradient id="s" x2="0" y2="100%"><stop offset="0" stop-color="#bbb" stop-opacity=".1"/><stop offset="1" stop-opacity=".1"/></linearGradient>
  <clipPath id="r"><rect width="${width}" height="20" rx="3" fill="#fff"/></clipPath>
  <g clip-path="url(#r)">
    <rect width="${labelWidth}" height="20" fill="${COLOR_LABEL}"/>
    <rect x="${labelWidth}" width="${messageWidth}" height="20" fill="${color}"/>
    <rect width="${width}" height="20" fill="url(#s)"/>
  </g>
  <g transform="translate(${PAD} 3)">
    <rect width="7.9" height="14" rx="1" fill="#2b5fad"/>
    <rect x="8.8" width="5.2" height="6.1" rx="1" fill="#6fa0e6"/>
    <rect x="8.8" y="7" width="5.2" height="7" rx="1" fill="#1a8a4a"/>
  </g>
  <g font-family="Verdana,Geneva,DejaVu Sans,sans-serif" font-size="11">${text(labelTextX, label, labelTextWidth)}${text(messageTextX, message, messageTextWidth)}
  </g>
</svg>
`;
}

/**
 * The same badge as a shields.io endpoint document
 * (https://shields.io/badges/endpoint-badge), for a maintainer who wants
 * one of shields' own styles (`for-the-badge`, `flat-square`, …) instead.
 */
export function buildShieldsEndpoint({ label, message, color }) {
  return { schemaVersion: 1, label, message, color: color.replace(/^#/, "") };
}

/**
 * The copy-pasteable snippets the project page's badge panel offers:
 * Markdown for a README, HTML for anywhere else. `badgeUrl` is the SVG,
 * `projectUrl` the project's awesomemap page the badge links to.
 */
export function buildBadgeSnippets({ badgeUrl, projectUrl, endpointUrl }) {
  return {
    markdown: `[![awesomemap](${badgeUrl})](${projectUrl})`,
    html: `<a href="${escapeXml(projectUrl)}"><img src="${escapeXml(badgeUrl)}" alt="awesomemap" /></a>`,
    shields: `[![awesomemap](https://img.shields.io/endpoint?url=${encodeURIComponent(endpointUrl)}&style=for-the-badge)](${projectUrl})`,
  };
}
